 private android.app.Application app;private int port;
 @Before public void setup()throws Exception{
  app=RuntimeEnvironment.getApplication();RouteIdentityTest.Secrets.store.clear();app.getSharedPreferences(ServerConfig.PREFS,0).edit().clear().putInt(ServerConfig.KEY_CONFIG_VERSION,3).commit();
  try(ServerSocket socket=new ServerSocket(0)){port=socket.getLocalPort();}app.getSharedPreferences(EmbeddedServerService.PREFS,0).edit().clear().putInt("port",port).putString("user","localls").putBoolean("server_role",true).putBoolean("show_client",false).commit();
  var gen=KeyPairGenerator.getInstance("RSA");gen.initialize(2048);ServerLifecycleTest.Identity.pair=gen.generateKeyPair();ServerLifecycleTest.Receive.hold=false;ServerLifecycleTest.Receive.entered=new CountDownLatch(1);ServerLifecycleTest.Receive.release=new CountDownLatch(1);
  EmbeddedServerService.running=false;EmbeddedServerService.starting=false;EmbeddedServerService.launchRequested=0;ServerInvitation.reset();ThemeCatalog.select(app,1);
 }
 private void await(java.util.function.BooleanSupplier condition)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);while(!condition.getAsBoolean()&&System.nanoTime()<until){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertTrue(EmbeddedServerService.status,condition.getAsBoolean());}
 private void cleanup(EmbeddedServerService service)throws Exception{assertTrue(ReflectionHelpers.<ExecutorService>getField(service,"worker").awaitTermination(10,TimeUnit.SECONDS));}
 @Test public void inlineQrRaisesAnOwnerConfirmationAndAccessStillRequiresExplicitApproval()throws Exception{
  var service=Robolectric.buildService(EmbeddedServerService.class).create();String pin;org.json.JSONObject identity=SshKeys.generate();String publicKey=identity.getString(SshKeys.PUBLIC);SshCredentials credential=SshCredentials.key(identity.getString(SshKeys.PRIVATE),"");
  try{service.get().onStartCommand(new Intent(app,EmbeddedServerService.class),0,1);await(()->EmbeddedServerService.running);pin=EmbeddedServerService.fingerprint;
   try(var owner=Robolectric.buildActivity(MainActivity.class).setup().visible()){
    MainActivity a=owner.get();View root=root(a);layout(root,411,890);ServerHomeLayout home=a.findViewById(R.id.serverHome);await(()->!ReflectionHelpers.<Boolean>getField(home,"reading"));home.setQrShown(true);await(()->ReflectionHelpers.getField(home,"bitmap")!=null);QrPairing invite=ReflectionHelpers.getField(home,"invitation");
    assertFalse(SftpClient.pairingAttempt(invite.host,port,invite.user,invite.nonce,credential,pin));assertEquals(EmbeddedSftpServer.normalizeAuthorizedKey(publicKey),EmbeddedServerService.pendingQrKey(invite.nonce));assertFalse(SftpClient.loginAttempt(invite.host,port,invite.user,credential,pin));
    await(()->{home.refresh();return org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()!=null;});AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(Shadows.shadowOf(dialog).getMessage().toString().contains(invite.syncCode(publicKey)));assertEquals(0,ServerDevices.count(app));capture(dialog.getWindow().getDecorView(),"01-owner-confirmation");
    dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();Intent command;do{command=Shadows.shadowOf(app).getNextStartedService();}while(command!=null&&!EmbeddedServerService.AUTHORIZE_QR.equals(command.getAction()));assertNotNull("Owner confirmation must request durable authorization",command);service.get().onStartCommand(command,0,2);await(()->ServerDevices.contains(app,publicKey));
    assertTrue(SftpClient.loginAttempt(invite.host,port,invite.user,credential,pin));assertEquals(pin,EmbeddedServerService.fingerprint);home.setQrShown(false);assertEquals(1,ServerDevices.count(app));
    try(SftpClient.TreeSession files=new SftpClient.TreeSession(invite.host,port,invite.user,credential,pin)){byte[] bytes={3,1,4};String path=files.write("/","qr-inline.bin",new java.io.ByteArrayInputStream(bytes),bytes.length,(n,total)->true);java.io.ByteArrayOutputStream received=new java.io.ByteArrayOutputStream();files.read(path,received,(n,total)->true);assertArrayEquals(bytes,received.toByteArray());}
    home.setQrShown(true);await(()->{QrPairing next=ReflectionHelpers.getField(home,"invitation");return next!=null&&!next.nonce.equals(invite.nonce);});QrPairing next=ReflectionHelpers.getField(home,"invitation");var second=SshKeys.generate();SshCredentials secondCredential=SshCredentials.key(second.getString(SshKeys.PRIVATE),"");assertFalse(SftpClient.pairingAttempt(next.host,port,next.user,next.nonce,secondCredential,pin));
    await(()->{home.refresh();return org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()!=dialog;});AlertDialog secondDialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(Shadows.shadowOf(secondDialog).getMessage().toString().contains(next.syncCode(second.getString(SshKeys.PUBLIC))));secondDialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse("Cancel must not grant the second device access",SftpClient.loginAttempt(next.host,port,next.user,secondCredential,pin));assertTrue("New QR must not revoke the first device",SftpClient.loginAttempt(next.host,port,next.user,credential,pin));assertEquals(1,ServerDevices.count(app));home.refresh();Shadows.shadowOf(Looper.getMainLooper()).idle();assertSame("Cancel must not cause an immediate repeated popup",secondDialog,org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());home.setQrShown(false);home.setQrShown(true);await(()->{home.refresh();return org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()!=secondDialog;});assertFalse("Showing the pending request again still needs consent",SftpClient.loginAttempt(next.host,port,next.user,secondCredential,pin));
   }
  }finally{service.destroy();cleanup(service.get());}
  var restarted=Robolectric.buildService(EmbeddedServerService.class).create();try{restarted.get().onStartCommand(new Intent(app,EmbeddedServerService.class),0,3);await(()->EmbeddedServerService.running);assertEquals(pin,EmbeddedServerService.fingerprint);assertTrue(SftpClient.loginAttempt("127.0.0.1",port,"localls",credential,pin));}finally{restarted.destroy();cleanup(restarted.get());}
 }
