 @Test public void closingTheFullOfferKeepsPendingApprovalReachableOnMainWithoutAnotherScan()throws Exception{
  var service=Robolectric.buildService(EmbeddedServerService.class).create();try{service.get().onStartCommand(new Intent(app,EmbeddedServerService.class),0,1);await(()->EmbeddedServerService.running);
   try(var owner=Robolectric.buildActivity(MainActivity.class).setup().visible()){
    MainActivity a=owner.get();layout(root(a),411,890);owner.pause();QrPairing invite;var identity=SshKeys.generate();SshCredentials key=SshCredentials.key(identity.getString(SshKeys.PRIVATE),"");
    try(var full=Robolectric.buildActivity(QrPairingActivity.class,new Intent(app,QrPairingActivity.class).putExtra("server",true)).setup().visible()){invite=ReflectionHelpers.getField(full.get(),"invitation");assertFalse(SftpClient.pairingAttempt(invite.host,port,invite.user,invite.nonce,key,invite.pin));}
    assertEquals("Back navigation must not discard an outstanding request",EmbeddedSftpServer.normalizeAuthorizedKey(identity.getString(SshKeys.PUBLIC)),EmbeddedServerService.pendingQrKey(invite.nonce));owner.resume();ServerHomeLayout home=a.findViewById(R.id.serverHome);await(()->{home.refresh();return org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()!=null;});assertTrue(Shadows.shadowOf(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()).getMessage().toString().contains(invite.syncCode(identity.getString(SshKeys.PUBLIC))));assertFalse(SftpClient.loginAttempt(invite.host,port,invite.user,key,invite.pin));assertEquals(0,ServerDevices.count(app));
   }
  }finally{service.destroy();cleanup(service.get());}
 }
